from __future__ import absolute_import

import csv

import time

from taf.selenium.core.download_tools import Downloader
from .common_page import CommonPage
from .panels.view import ViewPanel


class Performance(CommonPage):
    """
    The class corresponding to performance  page on selenium_coam_vdu web, all operations under performance
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Performance": PerformancePage(driver, version)}
        super(Performance, self).__init__(driver, version, self._instance_dict)


class PerformancePage(object):
    """
    As a class will be called by Performance, all operations Performance will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['chart-bar', 'Performance']

    def __init__(self, driver, version):
        self._view_panel = PerformancePageViewPanel(driver, version)

    def get_pm_counters(self, object_class_name, download_dir, timeout):
        """
        This keyword will return pm counter file and dictionary of the pm counters

        :param str/list object_class_name: object class name to filtered consisting of
                                           object_class/counter_id/object_name
                                           e.g. object_class_name='ETHLK/M51301C0/ETHLK-1' or
                                           object_class_name=['ETHLK/M51301C0/ETHLK-1',
                                           'ETHLK/M51301C2/ETHLK-2', 'VLANIF/M51302C1/VLANIF-1']
        :param download_dir: str, directory of the download location
        :param timeout: str, timeout for the element be available to click

        :return dict , returns the dictionary of counter file and dictionary of the pm counters
        """
        return self._view_panel.get_pm_counters(object_class_name, download_dir, timeout)


class PerformancePageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(PerformancePageViewPanel, self).__init__(driver, version)

    def get_pm_counters(self, object_class_name, download_dir, timeout):
        """
        This keyword will return pm counter file and dictionary of the pm counters

        :param str/list object_class_name: object class name to filtered consisting of
                                           object_class/counter_id/object_name
                                           e.g. object_class_name='ETHLK/M51301C0/ETHLK-1' or
                                           object_class_name=['ETHLK/M51301C0/ETHLK-1',
                                           'ETHLK/M51301C2/ETHLK-2', 'VLANIF/M51302C1/VLANIF-1']
        :param download_dir: str, directory of the download location
        :param timeout: str, timeout for the element be available to click

        :return dict , returns the dictionary of counter file and dictionary of the pm counters
        """
        start_time = time.time()
        self.filter_pm_counters(object_class_name, timeout)
        self.wait_for_visibility(self.locator.PM_TABLE, timeout=10)
        self.click_enabled_element(self.locator.SAVE_PM_COUNTERS, timeout)
        return self.download_and_parse_csv_file(download_dir, start_time)

    def filter_pm_counters(self, object_class_name, timeout):
        """
        This keyword will open and apply the filter for pm counters

        :param str/list object_class_name: object class name to filtered consisting of
                                           object_class/counter_id/object_name
                                           e.g. object_class_name='ETHLK/M51301C0/ETHLK-1' or
                                           object_class_name=['ETHLK/M51301C0/ETHLK-1',
                                           'ETHLK/M51301C2/ETHLK-2', 'VLANIF/M51302C1/VLANIF-1']
        :param timeout: str, timeout for the element be available to click

        :return dict , returns the dictionary of counter file and dictionary of the pm counters
        """
        self.wait_for_enable(self.locator.PERFORMANCE_FILTER_XPATH, timeout)
        self.click_enabled_element(self.locator.PERFORMANCE_FILTER_XPATH, timeout)
        object_class_name = [object_class_name] if isinstance(object_class_name, str) else object_class_name
        for item in object_class_name:
            object_class, counter_id, object_name = item.split("/")
            self.insert_text_to_enable_element(self.locator.OBJECT_CLASS_FILTER, object_class, timeout)
            if not self.element_exists(self.locator.CHECK_OBJECT_CLASS_SELECTED_XPATH.format(object_class), 2):
                self.click_enabled_element(self.locator.SELECT_OBJECT_CLASS_XPATH.format(object_class), timeout)
            self.insert_text_to_enable_element(self.locator.COUNTER_ID_FILTER_ID, counter_id, timeout)
            self.click_enabled_element(self.locator.SELECT_COUNTER_ID_XPATH.format(counter_id), timeout)
            self.insert_text_to_enable_element(self.locator.OBJECT_FILTER, object_name, timeout)
            self.wait_for_enable(self.locator.OBJECT_TREE, timeout)
            self.wait_for_visibility(self.locator.SELECT_OBJECT_CLASS, timeout)
            time.sleep(5)
            self.click_enabled_element(self.locator.SELECT_OBJECT_CLASS, timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)

    @staticmethod
    def download_and_parse_csv_file(download_dir, start_time):
        """
        This keyword will parse the downloaded csv file and convert it into list

        :param download_dir: str, directory of the download location
        :param start_time: time, start time of the download

        :return dict , returns the dictionary of counter file and dictionary of the pm counters in list of tuples
        """
        pm_counters = []
        downloaded_csv_file = Downloader().download(download_dir, start_time)
        with open(downloaded_csv_file, 'r') as csv_file:
            columns = list(zip(*csv.reader(csv_file)))
            for index in range(1, len(columns)):
                pm_counters.append(dict(zip(columns[0], columns[index])))
        return {"file": downloaded_csv_file, "counters": pm_counters}
